/**
 * Restore an interval, including intervals serialized with Carbon 2 where
 * the timezone property was still named "tzName".
 */
public function __unserialize(array $data): void
{
    parent::__construct(static::PERIOD_PREFIX.'0'.static::PERIOD_YEARS);

    foreach ($data as $key => $value) {
        $name = str_contains($key, "\0") ? substr($key, strrpos($key, "\0") + 1) : $key;

        if (\in_array($name, ['', 'days', 'from_string', 'date_string'], true)) {
            continue;
        }

        if ($name === 'tzName') {
            $name = 'timezoneSetting';
        }

        $this->$name = $value;
    }
}

